"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["18303"],{79190(e){e.exports=JSON.parse('{"id":"V4-207","slug":"real-assets","term":"Real Assets","also_known_as":[],"difficulty":"Intermediate","definition":"Real assets are physical or tangible assets that have value because of their substance and properties, such as real estate, infrastructure, land, commodities, timber and natural resources.","explanation":["Real assets differ from financial assets, such as shares and bonds, which represent claims on future cash flows. Real assets have intrinsic value from their physical nature and use.","Investors often value real assets for several reasons. Many provide steady income, such as rent from property or fees from infrastructure. Their values and income often rise with inflation, providing a hedge against rising prices. They can also diversify portfolios, because their returns often behave differently from shares and bonds.","For example, a pension fund might invest in a portfolio of toll roads, wind farms, farmland and logistics warehouses, earning income linked to inflation over many decades.","Real assets have drawbacks. Many are illiquid and expensive to buy and sell. They require active management and maintenance, and they are exposed to risks such as physical damage, regulation, climate change and changes in demand. Values are often based on appraisals rather than market prices.","Investors can access real assets directly or through funds, real estate investment trusts, listed infrastructure companies and commodity investments."],"note":"","total":1725,"prev":{"slug":"raw-materials","term":"Raw Materials"},"next":{"slug":"real-estate-investment-trust","term":"Real Estate Investment Trust (REIT)"}}')}}]);